### Frontend Starter - TLPS Production Planning Demo

**Assumptions:**
1. MAATAA UI components are available for integration.
2. Synthetic data generation rules will be defined by the backend team.
3. The frontend should not make any API calls to external systems.

**Acceptance Checks:**
1. Users can create a synthetic event brief with relevant details.
2. A timed call sheet is generated and reviewed by users.
3. Crew assignments and readiness blockers are checked.
4. An illustrative handover can be exported.

### React/TypeScript Source Draft

Below is a simplified version of the frontend implementation using React and TypeScript. This starter includes basic components for creating an event brief, generating a call sheet, checking crew assignments, and exporting a handover document.

#### `EventBriefCreator.tsx`
```tsx
import React, { useState } from 'react';
import { Button, Form, Input } from '@maataa/ui';

interface EventBrief {
  name: string;
  date: Date;
  location: string;
  personnel: string[];
}

const EventBriefCreator: React.FC = () => {
  const [eventBrief, setEventBrief] = useState<EventBrief>({
    name: '',
    date: new Date(),
    location: '',
    personnel: [],
  });

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setEventBrief({ ...eventBrief, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    // Assuming backend will receive this data
    console.log('Event Brief Created:', eventBrief);
  };

  return (
    <Form onSubmit={handleSubmit}>
      <Form.Item label="Event Name">
        <Input name="name" value={eventBrief.name} onChange={handleInputChange} />
      </Form.Item>
      <Form.Item label="Date">
        <Input type="date" name="date" value={eventBrief.date.toISOString().split('T')[0]} onChange={handleInputChange} />
      </Form.Item>
      <Form.Item label="Location">
        <Input name="location" value={eventBrief.location} onChange={handleInputChange} />
      </Form.Item>
      <Form.Item label="Personnel">
        <Input
          name="personnel"
          value={eventBrief.personnel.join(',')}
          onChange={(e) => setEventBrief({ ...eventBrief, personnel: e.target.value.split(',') })}
        />
      </Form.Item>
      <Button type="primary" htmlType="submit">
        Create Event Brief
      </Button>
    </Form>
  );
};

export default EventBriefCreator;
```

#### `TimedCallSheetGenerator.tsx`
```tsx
import React from 'react';
import { Card, List } from '@maataa/ui';

interface Task {
  id: number;
  name: string;
  time: string;
}

const tasks: Task[] = [
  { id: 1, name: 'Task 1', time: '09:00' },
  { id: 2, name: 'Task 2', time: '10:00' },
  // More tasks...
];

const TimedCallSheetGenerator: React.FC = () => {
  return (
    <Card title="Timed Call Sheet">
      <List
        dataSource={tasks}
        renderItem={(item) => (
          <List.Item>
            {item.time} - {item.name}
          </List.Item>
        )}
      />
    </Card>
  );
};

export default TimedCallSheetGenerator;
```

